function validSDKEventValue(value: unknown, shape: SDKEventValueShape): boolean {
  if (shape.kind === 'optional')
    return value === null || validSDKEventValue(value, shape.value)
  if (shape.kind === 'array')
    return (
      Array.isArray(value) && value.every((item) => validSDKEventValue(item, shape.value))
    )
  if (shape.kind === 'number') return typeof value === 'number' && Number.isFinite(value)
  if (shape.kind === 'string' || shape.kind === 'description' || shape.kind === 'boolean')
    return typeof value === (shape.kind === 'description' ? 'string' : shape.kind)
  if (shape.kind === 'enum')
    return (
      typeof value === 'string' &&
      (shape.cases.includes(value) || (shape.open === true && value === 'unknown'))
    )
  if (shape.kind === 'verification')
    return Boolean(
      value &&
      typeof value === 'object' &&
      ((value as { case?: unknown }).case === 'verified' ||
        (value as { case?: unknown }).case === 'unverified') &&
      typeof (value as { jwsRepresentation?: unknown }).jwsRepresentation === 'string' &&
      ((value as { case: string; error?: unknown }).case === 'verified'
        ? (value as { error?: unknown }).error === null
        : typeof (value as { error?: unknown }).error === 'string')
    )
  if (shape.kind === 'result')
    return Boolean(
      value &&
      typeof value === 'object' &&
      ((value as { case?: unknown }).case === 'success'
        ? validSDKEventValue((value as { value?: unknown }).value, shape.value)
        : (value as { case?: unknown }).case === 'failure' &&
          typeof (value as { error?: unknown }).error === 'string')
    )
  if (shape.kind === 'associatedEnum') {
    if (!value || typeof value !== 'object') return false
    if (shape.open && (value as { case?: unknown }).case === 'unknown')
      return (
        Array.isArray((value as { values?: unknown }).values) &&
        (value as { values: unknown[] }).values.length === 0
      )
    const item = shape.cases.find(
      (entry) => entry.name === (value as { case?: unknown }).case
    )
    return Boolean(
      item &&
      Array.isArray((value as { values?: unknown }).values) &&
      (value as { values: unknown[] }).values.length === item.values.length &&
      item.values.every((nested, index) =>
        validSDKEventValue((value as { values: unknown[] }).values[index], nested)
      )
    )
  }
  if (!value || typeof value !== 'object') return false
  const record = value as Record<string, unknown>
  if (shape.kind === 'point')
    return (
      typeof record.x === 'number' &&
      Number.isFinite(record.x) &&
      typeof record.y === 'number' &&
      Number.isFinite(record.y)
    )
  if (shape.kind === 'size')
    return (
      typeof record.width === 'number' &&
      Number.isFinite(record.width) &&
      typeof record.height === 'number' &&
      Number.isFinite(record.height)
    )
  if (shape.kind !== 'object') return false
  return shape.fields.every(
    (field) =>
      Object.hasOwn(record, field.name) &&
      validSDKEventValue(record[field.name], field.value)
  )
}

export function swiftStyleNative(
  style: OneNativeStyle | undefined
): OneNativeStyleNative | undefined {
  if (!style) return undefined
  const native: Record<string, unknown> = {}
  const sdkModifiers: [string, string][] = []
  for (const [name, value] of Object.entries(style)) {
    if (value === undefined) continue
    if (Object.hasOwn(sdkKinds, name)) {
      const kind = sdkKinds[name as keyof typeof sdkKinds]
      if (kind === 'record') {
        if (typeof value !== 'object' || value === null || Array.isArray(value))
          throw new Error(name + ' must be a record')
        const record = value as Record<string, unknown>
        const values = sdkRecords[name].map((argument) => {
          const item = record[argument.field]
          if (argument.optional && item === null) return null
          if (argument.kind === 'bindingBoolean') {
            if (
              !item ||
              typeof item !== 'object' ||
              typeof (item as { value?: unknown }).value !== 'boolean' ||
              typeof (item as { onChange?: unknown }).onChange !== 'function'
            )
              throw new Error(name + '.' + argument.field + ' must be a boolean binding')
            return String((item as { value: boolean }).value)
          }
          if (argument.kind === 'bindingOptionalURL') {
            if (
              !item ||
              typeof item !== 'object' ||
              ((item as { value?: unknown }).value !== null &&
                typeof (item as { value?: unknown }).value !== 'string') ||
              typeof (item as { onChange?: unknown }).onChange !== 'function'
            )
              throw new Error(name + '.' + argument.field + ' must be a URL binding')
            return JSON.stringify((item as { value: string | null }).value)
          }
          if (
            argument.kind === 'resultURL' ||
            argument.kind === 'resultURLArray' ||
            argument.kind === 'eventStruct'
          ) {
            if (typeof item !== 'function')
              throw new Error(name + '.' + argument.field + ' must be a callback')
            return ''
          }
          if (argument.kind === 'classUpdate' || argument.kind === 'structUpdate') {
            if (
              !item ||
              typeof item !== 'object' ||
              Array.isArray(item) ||
              Object.keys(item).length === 0 ||
              Object.entries(item).some(([key, fieldValue]) => {
                const field = argument.fields?.find((entry) => entry.name === key)
                return (
                  !field ||
                  (field.type === 'Swift.Bool'
                    ? typeof fieldValue !== 'boolean'
                    : field.type.endsWith('?') && fieldValue === null
                      ? false
                      : typeof fieldValue !== 'string')
                )
              })
            )
              throw new Error(
                name +
                  '.' +
                  argument.field +
                  (argument.kind === 'classUpdate'
                    ? ' must be an SDK class update'
                    : ' must be an SDK struct update')
              )
            return JSON.stringify(item)
          }
          if (
            argument.kind === 'number' &&
            (typeof item !== 'number' || !Number.isFinite(item))
          )
            throw new Error(name + '.' + argument.field + ' must be finite')
          if (argument.kind === 'boolean' && typeof item !== 'boolean')
            throw new Error(name + '.' + argument.field + ' must be a boolean')
          if (
            (argument.kind === 'string' ||
              argument.kind === 'url' ||
              argument.kind === 'enum') &&
            typeof item !== 'string'
          )
            throw new Error(name + '.' + argument.field + ' must be a string')
          if (
            (argument.kind === 'stringArray' || argument.kind === 'stringSet') &&
            (!Array.isArray(item) || item.some((element) => typeof element !== 'string'))
          )
            throw new Error(name + '.' + argument.field + ' must be a string array')
          if (argument.kind === 'numericStruct' || argument.kind === 'numericTuple') {
            if (
              !item ||
              typeof item !== 'object' ||
              Array.isArray(item) ||
              Object.keys(item).length !== argument.fields!.length ||
              argument.fields!.some((field) => {
                const number = (item as Record<string, unknown>)[field.name]
                return (
                  typeof number !== 'number' ||
                  !Number.isFinite(number) ||
                  (field.integer && !Number.isSafeInteger(number))
                )
              })
            )
              throw new Error(name + '.' + argument.field + ' must be a numeric object')
            return JSON.stringify(item)
          }
          return argument.kind === 'stringArray' || argument.kind === 'stringSet'
            ? JSON.stringify(item)
            : String(item)
        })
        sdkModifiers.push([name, JSON.stringify(values)])
        continue
      }
      if (kind === 'gesture') {
        if (
          !value ||
          typeof value !== 'object' ||
          Array.isArray(value) ||
          typeof (value as { kind?: unknown }).kind !== 'string' ||
          !Object.hasOwn(sdkGestureOptions[name], (value as { kind: string }).kind) ||
          typeof (value as { onEnded?: unknown }).onEnded !== 'function'
        )
          throw new Error(name + ' must be an SDK gesture and callback')
        sdkModifiers.push([name, (value as { kind: string }).kind])
        continue
      }
      if (kind === 'visualEffect') {
        if (
          !value ||
          typeof value !== 'object' ||
          Array.isArray(value) ||
          typeof (value as { kind?: unknown }).kind !== 'string' ||
          !sdkVisualEffects[name].includes((value as { kind: string }).kind) ||
          typeof (value as { value?: unknown }).value !== 'number' ||
          !Number.isFinite((value as { value: number }).value)
        )
          throw new Error(name + ' must be a visual effect and finite value')
        sdkModifiers.push([
          name,
          JSON.stringify([
            (value as { kind: string }).kind,
            String((value as { value: number }).value),
          ]),
        ])
        continue
      }
      if (kind === 'optionSet') {
        if (!value || typeof value !== 'object' || Array.isArray(value))
          throw new Error(name + ' must be an SDK option set')
        const record = value as Record<string, unknown>
        const options: Record<string, string> = {}
        for (const [field, item] of Object.entries(record)) {
          const argument = sdkOptionSets[name].find((entry) => entry.field === field)
          if (!argument) throw new Error(name + '.' + field + ' is not an SDK option')
          if (
            argument.kind === 'number' &&
            (typeof item !== 'number' || !Number.isSafeInteger(item))
          )
            throw new Error(name + '.' + field + ' must be finite')
          if (argument.kind === 'boolean' && typeof item !== 'boolean')
            throw new Error(name + '.' + field + ' must be a boolean')
          if (argument.kind === 'string' && typeof item !== 'string')
            throw new Error(name + '.' + field + ' must be a string')
          options[field] = String(item)
        }
        sdkModifiers.push([name, JSON.stringify(options)])
        continue
      }
      if (kind === 'eventAsyncStruct' && sdkAsyncArguments[name]) {
        if (
          !value ||
          typeof value !== 'object' ||
          Array.isArray(value) ||
          typeof (value as { onAction?: unknown }).onAction !== 'function'
        )
          throw new Error(name + ' must be an async SDK callback and arguments')
        const record = value as Record<string, unknown>
        const argumentsFromSDK = sdkAsyncArguments[name].map(({ field, kind }) => {
          const item = record[field]
          if (kind === 'stringArray') {
            if (!Array.isArray(item) || item.some((value) => typeof value !== 'string'))
              throw new Error(name + '.' + field + ' must be a string array')
            return JSON.stringify(item)
          }
          if (typeof item !== 'string')
            throw new Error(name + '.' + field + ' must be a string')
          return item
        })
        sdkModifiers.push([name, JSON.stringify(argumentsFromSDK)])
        continue
      }
      if (kind === 'number' && (typeof value !== 'number' || !Number.isFinite(value)))
        throw new Error(name + ' must be finite')
      if (
        kind === 'optionalNumber' &&
        value !== null &&
        (typeof value !== 'number' || !Number.isFinite(value))
      )
        throw new Error(name + ' must be finite or null')
      if (
        (kind === 'boolean' || kind === 'defaultFocusBoolean') &&
        typeof value !== 'boolean'
      )
        throw new Error(name + ' must be a boolean')
      if (kind === 'optionalBoolean' && value !== null && typeof value !== 'boolean')
        throw new Error(name + ' must be a boolean or null')
      if (kind === 'string' && typeof value !== 'string')
        throw new Error(name + ' must be a string')
      if (kind === 'selectionID' && typeof value !== 'string')
        throw new Error(name + ' must be a string')
      if (kind === 'url' && typeof value !== 'string')
        throw new Error(name + ' must be a URL string')
      if (kind === 'optionalURL' && value !== null && typeof value !== 'string')
        throw new Error(name + ' must be a URL string or null')
      if (kind === 'optionalEnum' && value !== null && typeof value !== 'string')
        throw new Error(name + ' must be a string or null')
      if (kind === 'optionalString' && value !== null && typeof value !== 'string')
        throw new Error(name + ' must be a string or null')
      if (
        kind.startsWith('event') &&
        kind !== 'eventValueString' &&
        kind !== 'eventReturnArray' &&
        kind !== 'eventReturnEnum' &&
        typeof value !== 'function'
      )
        throw new Error(name + ' must be a callback')
      if (
        kind === 'eventValueString' &&
        (typeof value !== 'object' ||
          value === null ||
          typeof (value as { value?: unknown }).value !== 'string' ||
          typeof (value as { onChange?: unknown }).onChange !== 'function')
      )
        throw new Error(name + ' must be a string value and callback')
      if (
        kind === 'eventReturnArray' &&
        (typeof value !== 'object' ||
          value === null ||
          !Array.isArray((value as { items?: unknown }).items) ||
          !(value as { items: unknown[] }).items.every(
            (item) => typeof item === 'string'
          ) ||
          typeof (value as { onAction?: unknown }).onAction !== 'function')
      )
        throw new Error(name + ' must be a string array and callback')
      if (
        kind === 'eventReturnEnum' &&
        (typeof value !== 'object' ||
          value === null ||
          typeof (value as { result?: unknown }).result !== 'string' ||
          !sdkEventCases[name].includes((value as { result: string }).result) ||
          typeof (value as { onAction?: unknown }).onAction !== 'function')
      )
        throw new Error(name + ' must be an SDK result and callback')
      if (
        (kind === 'bindingBoolean' ||
          kind === 'bindingFocusBoolean' ||
          kind === 'bindingString' ||
          kind === 'bindingOptionalString' ||
          kind === 'bindingCodable') &&
        (typeof value !== 'object' ||
          value === null ||
          typeof (value as { onChange?: unknown }).onChange !== 'function' ||
          (kind === 'bindingOptionalString' ||
          (kind === 'bindingCodable' && sdkCodableOptional[name])
            ? (value as { value?: unknown }).value !== null &&
              typeof (value as { value?: unknown }).value !== 'string'
            : typeof (value as { value?: unknown }).value !==
              (kind === 'bindingBoolean' || kind === 'bindingFocusBoolean'
                ? 'boolean'
                : 'string')))
      )
        throw new Error(name + ' must be a binding')
      if (kind === 'bindingCodable' && (value as { value: string | null }).value !== null)
        JSON.parse((value as { value: string }).value)
      if (
        kind === 'bindingPoint' &&
        (typeof value !== 'object' ||
          value === null ||
          typeof (value as { onChange?: unknown }).onChange !== 'function' ||
          ((value as { value?: unknown }).value !== null &&
            !validSDKEventValue((value as { value?: unknown }).value, { kind: 'point' })))
      )
        throw new Error(name + ' must be a point binding')
      sdkModifiers.push([
        name,
        kind === 'eventValueString'
          ? (value as { value: string }).value
          : kind === 'eventReturnArray'
            ? JSON.stringify((value as { items: string[] }).items)
            : kind === 'eventReturnEnum'
              ? (value as { result: string }).result
              : kind.startsWith('event')
                ? ''
                : kind === 'bindingOptionalString' || kind === 'bindingPoint'
                  ? JSON.stringify((value as { value: unknown }).value)
                  : kind === 'bindingCodable' &&
                      (value as { value: string | null }).value === null
                    ? 'null'
                    : kind.startsWith('binding')
                      ? String((value as { value: unknown }).value)
                      : kind === 'optionalString' || kind === 'optionalURL'
                        ? (JSON.stringify(value) as string)
                        : String(value),
      ])
    } else if (colorFields.includes(name as (typeof colorFields)[number])) {
      native[name] = processColor(value as ColorValue) ?? undefined
    } else {
      native[name] = value
    }
  }
  if (sdkModifiers.length) native.sdkModifiers = JSON.stringify(sdkModifiers)
  return native as OneNativeStyleNative
}

export function dispatchSDKEvent(
  style: OneNativeStyle | undefined,
  name: string,
  value: string
): void {
  const separator = name.indexOf('.')
  if (separator !== -1) {
    const parent = name.slice(0, separator)
    const field = name.slice(separator + 1)
    if (
      sdkRecords[parent]?.some(
        (argument) => argument.field === field && argument.kind === 'bindingBoolean'
      )
    ) {
      if (value !== 'true' && value !== 'false')
        throw new Error(name + ' emitted an invalid boolean')
      const record = (style as Record<string, unknown> | undefined)?.[parent] as
        | Record<string, unknown>
        | undefined
      ;(record?.[field] as { onChange: (value: boolean) => void } | undefined)?.onChange(
        value === 'true'
      )
      return
    }
    if (
      sdkRecords[parent]?.some(
        (argument) => argument.field === field && argument.kind === 'bindingOptionalURL'
      )
    ) {
      const decoded: unknown = JSON.parse(value)
      if (decoded !== null && typeof decoded !== 'string')
        throw new Error(name + ' emitted an invalid URL')
      const record = (style as Record<string, unknown> | undefined)?.[parent] as
        | Record<string, unknown>
        | undefined
      ;(
        record?.[field] as { onChange: (value: string | null) => void } | undefined
      )?.onChange(decoded)
      return
    }
    const result = sdkRecords[parent]?.find(
      (argument) =>
        argument.field === field &&
        (argument.kind === 'resultURL' || argument.kind === 'resultURLArray')
    )
    if (result) {
      const decoded: unknown = JSON.parse(value)
      if (!decoded || typeof decoded !== 'object' || Array.isArray(decoded))
        throw new Error(name + ' emitted an invalid result')
      const payload = decoded as Record<string, unknown>
      const success = payload.success
      const failure = payload.failure
      const validSuccess =
        result.kind === 'resultURL'
          ? typeof success === 'string'
          : Array.isArray(success) && success.every((item) => typeof item === 'string')
      if (
        !(
          (validSuccess && failure === undefined) ||
          (success === undefined && typeof failure === 'string')
        ) ||
        Object.keys(payload).length !== 1
      )
        throw new Error(name + ' emitted an invalid result')
      const record = (style as Record<string, unknown> | undefined)?.[parent] as
        | Record<string, unknown>
        | undefined
      ;(record?.[field] as ((result: unknown) => void) | undefined)?.(payload)
      return
    }
    const event = sdkRecords[parent]?.find(
      (argument) => argument.field === field && argument.kind === 'eventStruct'
    )
    if (event) {
      const payload: unknown = JSON.parse(value)
      if (!validSDKEventValue(payload, event.eventValue!))
        throw new Error(name + ' emitted an invalid struct value')
      const record = (style as Record<string, unknown> | undefined)?.[parent] as
        | Record<string, unknown>
        | undefined
      ;(record?.[field] as ((value: unknown) => void) | undefined)?.(payload)
      return
    }
  }
  const modifier = (style as Record<string, unknown> | undefined)?.[name]
  const kind = sdkKinds[name as keyof typeof sdkKinds] as string | undefined
  if (kind === 'gesture') {
    const config = modifier as
      | { kind: string; onEnded: (value?: unknown) => void }
      | undefined
    const shape = config && sdkGestureOptions[name]?.[config.kind]
    if (shape === undefined) throw new Error(name + ' emitted an invalid gesture')
    if (shape === null) {
      if (value !== '') throw new Error(name + ' emitted an invalid gesture event')
      config?.onEnded()
    } else {
      const payload: unknown = JSON.parse(value)
      if (!validSDKEventValue(payload, shape))
        throw new Error(name + ' emitted an invalid gesture event')
      config?.onEnded(payload)
    }
  } else if (kind === 'event') (modifier as (() => void) | undefined)?.()
  else if (kind === 'eventAsync') {
    const native = NativeModules.OneNativeAsyncActionModule as
      | { complete(identifier: string): void }
      | undefined
    if (!native) throw new Error('OneNativeAsyncActionModule is unavailable')
    void Promise.resolve()
      .then(() => (modifier as (() => void | Promise<void>) | undefined)?.())
      .finally(() => native.complete(value))
  } else if (kind === 'eventAsyncStruct') {
    const native = NativeModules.OneNativeAsyncActionModule as
      | { complete(identifier: string): void }
      | undefined
    if (!native) throw new Error('OneNativeAsyncActionModule is unavailable')
    const envelope: unknown = JSON.parse(value)
    if (
      !envelope ||
      typeof envelope !== 'object' ||
      typeof (envelope as { id?: unknown }).id !== 'string' ||
      typeof (envelope as { value?: unknown }).value !== 'string'
    )
      throw new Error(name + ' emitted an invalid async event')
    const identifier = (envelope as { id: string }).id
    const payload: unknown = JSON.parse((envelope as { value: string }).value)
    if (!validSDKEventValue(payload, sdkEventStructs[name]))
      throw new Error(name + ' emitted an invalid async value')
    const action =
      typeof modifier === 'function'
        ? modifier
        : (
            modifier as
              | { onAction?: (value: unknown) => void | Promise<void> }
              | undefined
          )?.onAction
    void Promise.resolve()
      .then(() => action?.(payload))
      .finally(() => native.complete(identifier))
  } else if (kind === 'eventReturnArray')
    (modifier as { onAction: () => void } | undefined)?.onAction()
  else if (kind === 'eventReturnEnum') {
    const payload: unknown = JSON.parse(value)
    if (!validSDKEventValue(payload, sdkEventStructs[name]))
      throw new Error(name + ' emitted an invalid result event')
    ;(modifier as { onAction: (value: unknown) => void } | undefined)?.onAction(payload)
  } else if (kind === 'eventBoolean') {
    if (value !== 'true' && value !== 'false')
      throw new Error(name + ' emitted an invalid boolean')
    ;(modifier as ((value: boolean) => void) | undefined)?.(value === 'true')
  } else if (kind === 'eventNumber') {
    const number = Number(value)
    if (!Number.isFinite(number)) throw new Error(name + ' emitted an invalid number')
    ;(modifier as ((value: number) => void) | undefined)?.(number)
  } else if (kind === 'eventString')
    (modifier as ((value: string) => void) | undefined)?.(value)
  else if (kind === 'eventEnum') {
    if (!sdkEventCases[name].includes(value))
      throw new Error(name + ' emitted an invalid enum value')
    ;(modifier as ((value: string) => void) | undefined)?.(value)
  } else if (kind === 'eventEnumPair') {
    const pair: unknown = JSON.parse(value)
    if (
      !Array.isArray(pair) ||
      pair.length !== 2 ||
      pair.some((item) => typeof item !== 'string' || !sdkEventCases[name].includes(item))
    )
      throw new Error(name + ' emitted invalid enum values')
    ;(modifier as ((oldValue: string, newValue: string) => void) | undefined)?.(
      pair[0],
      pair[1]
    )
  } else if (kind === 'eventAssociatedEnum') {
    const payload: unknown = JSON.parse(value)
    if (!payload || typeof payload !== 'object')
      throw new Error(name + ' emitted an invalid enum payload')
    const event = payload as { case?: unknown; values?: unknown }
    const kinds =
      typeof event.case === 'string' ? sdkAssociatedCases[name]?.[event.case] : undefined
    if (!kinds || !Array.isArray(event.values) || event.values.length !== kinds.length)
      throw new Error(name + ' emitted an invalid enum case')
    for (const [index, item] of event.values.entries()) {
      if (!validSDKEventValue(item, kinds[index]))
        throw new Error(name + ' emitted an invalid ' + kinds[index].kind)
    }
    ;(modifier as ((value: unknown) => void) | undefined)?.(event)
  } else if (kind === 'eventStruct') {
    const payload: unknown = JSON.parse(value)
    if (!validSDKEventValue(payload, sdkEventStructs[name]))
      throw new Error(name + ' emitted an invalid struct value')
    ;(modifier as ((value: unknown) => void) | undefined)?.(payload)
  } else if (kind === 'bindingBoolean' || kind === 'bindingFocusBoolean') {
    if (value !== 'true' && value !== 'false')
      throw new Error(name + ' emitted an invalid boolean')
    ;(modifier as { onChange: (value: boolean) => void } | undefined)?.onChange(
      value === 'true'
    )
  } else if (kind === 'bindingString' || kind === 'bindingCodable')
    (modifier as { onChange: (value: string) => void } | undefined)?.onChange(value)
  else if (kind === 'bindingOptionalString') {
    const decoded: unknown = JSON.parse(value)
    if (decoded !== null && typeof decoded !== 'string')
      throw new Error(name + ' emitted an invalid optional string')
    ;(modifier as { onChange: (value: string | null) => void } | undefined)?.onChange(
      decoded
    )
  } else if (kind === 'bindingPoint') {
    const decoded: unknown = JSON.parse(value)
    if (decoded !== null && !validSDKEventValue(decoded, { kind: 'point' }))
      throw new Error(name + ' emitted an invalid point')
    ;(
      modifier as
        | { onChange: (value: { x: number; y: number } | null) => void }
        | undefined
    )?.onChange(decoded as { x: number; y: number } | null)
  } else if (kind === 'eventValueString')
    (modifier as { onChange: (value: string) => void } | undefined)?.onChange(value)
}
